meta:
interface Meta {
  model: "gpt-4o" | "gpt-4o-mini";
  /** Sampling temperature (0-2). */
  temperature?: number;
}

template.schema:
/** A support ticket to be triaged. */
interface Input {
  subject: string;
  body: string;
}

interface Output {
  /** Broad category of the issue. */
  category: "billing" | "technicalIssue" | "featureRequest" | "other";

  /** How quickly this ticket needs attention. */
  urgency: "low" | "medium" | "high" | "critical";

  /** One-sentence summary of the issue. */
  summary: string;

  /** Suggested first response, if the issue is straightforward. */
  suggestedReply?: string;
}
